/**
 * Parses GHL's LLM-ready docs export (`docs/llms/v3/llms-full.txt`) into operation records.
 *
 * The export is generated by GHL from their OpenAPI specs and follows one fixed layout per
 * endpoint (see "How to read an endpoint" at the top of the file). Anything this parser does not
 * recognise is a hard error: a silent skip would mean a skill quietly missing operations.
 */

import type { GhlVersion, HttpMethod, SessionParam, TokenKind } from "@locus/ghl";

export type BodyType = "json" | "multipart" | "form";

export interface ParsedOperation {
  id: string;
  title: string;
  summary: string;
  method: HttpMethod;
  path: string;
  version: GhlVersion;
  tokens: TokenKind[];
  scopes: string[];
  sessionParams: SessionParam[];
  body?: BodyType;
  deprecated: boolean;
  docs: string;
}

export interface ParsedService {
  name: string;
  label: string;
  operations: ParsedOperation[];
  /** The service's section of the export, verbatim — the skill's reference material. */
  reference: string;
}

export interface ParsedDocs {
  version: string;
  services: ParsedService[];
  /** Defects in GHL's docs that do not stop generation, e.g. an undocumented path parameter. */
  warnings: string[];
}

const METHODS = new Set(["GET", "POST", "PUT", "PATCH", "DELETE"]);
const VERSIONS = new Set(["v4", "v3", "2023-02-21", "2021-07-28", "2021-04-15"]);
const TOKEN_KINDS: Record<string, TokenKind> = { "Sub-Account": "location", Agency: "agency" };

export class DocsParseError extends Error {
  override name = "DocsParseError";
}

export function parseDocs(text: string): ParsedDocs {
  const lines = text.replace(/\r\n/g, "\n").split("\n");
  const version = /^# HighLevel API (\S+): full reference/.exec(lines[0] ?? "")?.[1];
  if (!version) throw new DocsParseError("not a HighLevel full-reference export (line 1)");

  const services: ParsedService[] = [];
  const warnings: string[] = [];
  let i = 0;
  while (i < lines.length) {
    const header = /^## Service: (\S+) \((.*)\)$/.exec(lines[i] ?? "");
    if (!header) {
      i++;
      continue;
    }
    const start = i;
    let end = i + 1;
    while (end < lines.length && !lines[end]?.startsWith("## ")) end++;
    const section = lines.slice(start, end);
    services.push({
      name: header[1] as string,
      label: header[2] as string,
      operations: parseService(header[1] as string, section, warnings),
      reference: `${section.join("\n").trimEnd()}\n`,
    });
    i = end;
  }
  if (services.length === 0) throw new DocsParseError("no '## Service:' sections found");
  return { version, services, warnings };
}

function parseService(service: string, section: string[], warnings: string[]): ParsedOperation[] {
  const operations: ParsedOperation[] = [];
  const ids = new Set<string>();
  let i = 0;
  while (i < section.length) {
    if (!section[i]?.startsWith("### ")) {
      i++;
      continue;
    }
    let end = i + 1;
    while (end < section.length && !section[end]?.startsWith("### ")) end++;
    const op = parseOperation(service, section.slice(i, end), warnings);
    if (ids.has(op.id)) throw new DocsParseError(`duplicate operation id ${op.id}`);
    ids.add(op.id);
    operations.push(op);
    i = end;
  }
  return operations;
}

function parseOperation(service: string, block: string[], warnings: string[]): ParsedOperation {
  const title = (block[0] as string).slice(4).trim();
  const fail = (why: string): never => {
    throw new DocsParseError(`${service} / "${title}": ${why}`);
  };

  const route = /^([A-Z]+) (\/\S*)$/.exec(block[1] ?? "") ?? fail("no 'METHOD /path' line");
  const method = route[1] as string;
  if (!METHODS.has(method)) fail(`unknown method ${method}`);
  const path = route[2] as string;

  const docsLine = block.find((l) => l.startsWith("Docs: ")) ?? fail("no Docs line");
  const docs = /^Docs: (\S+)/.exec(docsLine)?.[1] as string;
  const slug = docs.split("/").at(-1) ?? fail("Docs URL has no slug");

  const authAt = block.findIndex((l) => l.startsWith("Auth"));
  if (authAt < 0) fail("no Auth line");
  const docsAt = block.indexOf(docsLine);
  const description = block
    .slice(docsAt + 1, authAt)
    .join("\n")
    .trim();

  const { tokens, scopes } = parseAuth(block, authAt, fail);

  const version = parseVersion(block, fail);
  // Every placeholder in the path is a required parameter, documented or not.
  const pathParams = paramList(block, "Path parameters:");
  for (const name of [...path.matchAll(/\{([^}]+)\}/g)].map((m) => m[1] as string)) {
    if (!pathParams.some((p) => p.name === name)) {
      warnings.push(`${service} / "${title}": path parameter {${name}} is undocumented`);
      pathParams.push({ name, required: true });
    }
  }
  const queryParams = paramList(block, "Query parameters:");
  const bodyAt = block.findIndex((l) => l.startsWith("Request body"));
  const bodyParams = bodyAt < 0 ? [] : fieldList(block, bodyAt + 1);
  const body = bodyAt < 0 ? undefined : bodyType(block[bodyAt] as string, fail);

  const sessionParams = [
    ...sessionParamsIn("path", pathParams),
    ...sessionParamsIn("query", queryParams),
    ...sessionParamsIn("body", bodyParams),
  ];

  return {
    id: `${service}.${slug}`,
    title,
    summary: firstSentence(description),
    method: method as HttpMethod,
    path,
    version,
    tokens,
    scopes,
    sessionParams,
    ...(body ? { body } : {}),
    deprecated: /\bdeprecated\b/i.test(description),
    docs,
  };
}

function parseAuth(
  block: string[],
  at: number,
  fail: (why: string) => never,
): { tokens: TokenKind[]; scopes: string[] } {
  const line = block[at] as string;
  if (line.startsWith("Auth: none")) return { tokens: [], scopes: [] };

  const entries = line.startsWith("Auth (any one of):")
    ? takeWhile(block, at + 1, (l) => l.startsWith("- ")).map((l) => l.slice(2))
    : [line.replace(/^Auth: /, "")];
  if (entries.length === 0) fail("empty Auth list");

  const tokens = new Set<TokenKind>();
  const scopes = new Set<string>();
  for (const entry of entries) {
    const kind = /^(Sub-Account|Agency) token:/.exec(entry)?.[1];
    if (!kind) fail(`unrecognised auth entry "${entry}"`);
    tokens.add(TOKEN_KINDS[kind as string] as TokenKind);
    const scope = /Scopes: (.+)$/.exec(entry)?.[1];
    for (const s of scope?.split(/,\s*/) ?? []) scopes.add(s.trim());
  }
  return { tokens: [...tokens].sort(), scopes: [...scopes].sort() };
}

function parseVersion(block: string[], fail: (why: string) => never): GhlVersion {
  const line = block.find((l) => l.startsWith("- Version: ")) ?? fail("no Version header");
  const version = /^- Version: (\S+)/.exec(line)?.[1] as string;
  if (!VERSIONS.has(version)) fail(`unknown version ${version}`);
  return version as GhlVersion;
}

interface Param {
  name: string;
  required: boolean;
}

function paramList(block: string[], heading: string): Param[] {
  const at = block.indexOf(heading);
  return at < 0 ? [] : fieldList(block, at + 1);
}

/** Top-level `- name*? type …` lines, stopping at the first blank line. */
function fieldList(block: string[], from: number): Param[] {
  const params: Param[] = [];
  for (const line of takeWhile(block, from, (l) => l.trim() !== "")) {
    const m = /^- (\S+?)(\*)? /.exec(line);
    if (m) params.push({ name: m[1] as string, required: m[2] === "*" });
  }
  return params;
}

function bodyType(line: string, fail: (why: string) => never): BodyType {
  if (line.includes("(application/json)")) return "json";
  if (line.includes("(multipart/form-data)")) return "multipart";
  if (line.includes("(application/x-www-form-urlencoded)")) return "form";
  return fail(`unknown request body type in "${line}"`);
}

/**
 * Parameters Locus fills from the session. `altId` only counts as the client when GHL pairs it
 * with `altType` in the same place.
 */
function sessionParamsIn(where: SessionParam["in"], params: Param[]): SessionParam[] {
  const names = new Set(params.map((p) => p.name));
  const result: SessionParam[] = [];
  for (const p of params) {
    const value =
      p.name === "locationId"
        ? "locationId"
        : p.name === "companyId"
          ? "companyId"
          : p.name === "altId" && names.has("altType")
            ? "locationId"
            : p.name === "altType" && names.has("altId")
              ? "altType"
              : undefined;
    if (value) result.push({ in: where, name: p.name, value, required: p.required });
  }
  return result;
}

function takeWhile(lines: string[], from: number, keep: (line: string) => boolean): string[] {
  const out: string[] = [];
  for (let i = from; i < lines.length && keep(lines[i] as string); i++)
    out.push(lines[i] as string);
  return out;
}

function firstSentence(description: string): string {
  const flat = description.replace(/\s+/g, " ").trim();
  const sentence = /^(.+?[.!?])(\s|$)/.exec(flat)?.[1] ?? flat;
  return sentence.length > 200 ? `${sentence.slice(0, 197)}...` : sentence;
}
